const body = $input.first().json.body ?? $input.first().json;
const event = body?.event ?? '';

// Só processar mensagens recebidas
if (event !== 'messages.upsert') {
  return [];
}

const data = body?.data;
if (!data) return [];

// Ignorar mensagens enviadas pelo próprio WhatsApp conectado
if (data?.key?.fromMe === true) {
  return [];
}

const remoteJid = data?.key?.remoteJid ?? '';

// Ignorar status/broadcast
if (remoteJid === 'status@broadcast') {
  return [];
}

// Ignorar grupos
if (remoteJid.includes('@g.us')) {
  return [];
}

// Bloquear @lid, pois não é número real e quebra o envio
if (remoteJid.includes('@lid')) {
  console.log(`[LID BLOQUEADO] ${remoteJid}`);
  return [];
}

// Validar se veio como número real do WhatsApp
if (!remoteJid.includes('@s.whatsapp.net')) {
  console.log(`[JID INVÁLIDO] ${remoteJid}`);
  return [];
}

// Extrair número limpo
const numero = remoteJid
  .replace('@s.whatsapp.net', '')
  .replace(/\D/g, '');

// Extrair texto da mensagem
const mensagem =
  data?.message?.conversation ??
  data?.message?.extendedTextMessage?.text ??
  data?.message?.imageMessage?.caption ??
  data?.message?.videoMessage?.caption ??
  '';

const mensagemLimpa = mensagem.trim();

if (!mensagemLimpa) {
  console.log('[MENSAGEM VAZIA OU TIPO NÃO SUPORTADO]');
  return [];
}

// Dados extras úteis
const pushName = data?.pushName ?? '';
const nome = pushName || 'Cliente';
const messageId = data?.key?.id ?? '';
const tipoMensagem = data?.messageType ?? 'desconhecido';
const timestamp = data?.messageTimestamp ?? Math.floor(Date.now() / 1000);
const dataHora = new Date(timestamp * 1000).toISOString();

return [
  {
    json: {
      numero,
      nome,
      pushName,
      mensagem: mensagemLimpa,
      remoteJid,
      messageId,
      tipoMensagem,
      timestamp,
      dataHora
    }
  }
];

const lead = $('Criar ou Atualizar Lead').first().json;
const mensagens = $('Buscar últimas mensagens').all().map(item => item.json);

// O banco busca da mais nova para a mais antiga.
// Aqui invertemos para enviar para a IA na ordem correta.
const historico = mensagens.reverse().map(msg => ({
  role: msg.role,
  content: msg.mensagem
}));

const conversaEmAndamento = historico.length > 1;

return [
  {
    json: {
      cliente: {
        telefone: lead.telefone,
        nome: lead.nome || 'Cliente',
        etapa_atual: lead.etapa_atual || 'inicio',
        projeto: lead.projeto || '',
        experiencia: lead.experiencia || '',
        cidade: lead.cidade || '',
        produto_interesse: lead.produto_interesse || '',
        bot_ativo: lead.bot_ativo
      },

      mensagem_atual: lead.mensagem_atual,
      remoteJid: lead.remote_jid_atual,

      historico_recente: historico,
      conversaEmAndamento,

      instrucao_curta: `
Responda como uma pessoa real no WhatsApp.

Antes de responder, leia o histórico recente.
Se a conversa já começou, não cumprimente novamente.
Não diga "Bem-vindo à Sua Empresa" no meio da conversa.
Não repita o nome do cliente em toda resposta.
Não pergunte algo que o cliente já respondeu.
Faça no máximo uma pergunta.
Não use lista.
Não use bullets.
Não escreva texto grande.
Responda em no máximo 320 caracteres.
A resposta precisa continuar naturalmente a conversa.
      `.trim()
    }
  }
];

if (['catalogo_produtos', 'detalhe_segmento', 'lead_facebook_inicial'].includes($json.intencao)) {
  return [];
}

// A chave vem do .env (ANTHROPIC_API_KEY). Nunca deixe a chave escrita no código.
const apiKey = $env.ANTHROPIC_API_KEY;

const cliente = $json.cliente || {};
const historico = Array.isArray($json.historico_recente) ? $json.historico_recente : [];

const mensagemAtual =
  $json.mensagem_atual ||
  $json.mensagem ||
  '';

const telefone =
  cliente.telefone ||
  $json.telefone ||
  $json.numero ||
  '';

const remoteJid =
  $json.remoteJid ||
  $json.remote_jid_atual ||
  $json.remote_jid ||
  (telefone ? `${telefone}@s.whatsapp.net` : '');

const nomeCliente =
  cliente.nome ||
  $json.nome ||
  $json.pushName ||
  $json.push_name ||
  'Cliente';

const siteOficial =
  $json.siteOficial ||
  'www.suaempresa.com.br';

const linksProdutos =
  $json.linksProdutos ||
  {};

const conversaEmAndamento =
  $json.conversaEmAndamento === true &&
  historico.length > 0;

// SAUDAÇÃO FIXA — início de conversa, sem histórico
if ($json.intencao === 'saudacao' && !conversaEmAndamento) {
  const textoResposta = `Olá. Seja muito bem-vindo à família Sua Empresa! 
Aqui é o Bia, e será um prazer te atender 😊

Como posso lhe ajudar hoje?

Você também pode conhecer todos os nossos produtos em:
www.suaempresa.com.br

E acompanhar novidades, inspirações e conteúdos no nosso Instagram:
@suaempresa 💫`;

  return [
    {
      json: {
        ...$json,
        numero: telefone,
        telefone,
        remoteJid,
        mensagem: mensagemAtual,
        pushName: nomeCliente,
        textoResposta,
        conversaEmAndamento,
        origemResposta: 'saudacao_inicial_completa'
      }
    }
  ];
}

// SAUDAÇÃO CURTA — quando já existe histórico/contexto
if ($json.intencao === 'saudacao' && conversaEmAndamento) {
  const textoResposta = `Olá! Aqui é o Bia, atendente virtual da Sua Empresa. Como posso te ajudar?`;

  return [
    {
      json: {
        ...$json,
        numero: telefone,
        telefone,
        remoteJid,
        mensagem: mensagemAtual,
        pushName: nomeCliente,
        textoResposta,
        conversaEmAndamento,
        origemResposta: 'saudacao_curta_com_contexto'
      }
    }
  ];
}

const dadosLead = {
  nome: nomeCliente,
  telefone,
  etapa_atual: cliente.etapa_atual || $json.etapa_atual || '',
  projeto: cliente.projeto || $json.projeto || '',
  experiencia: cliente.experiencia || $json.experiencia || '',
  cidade: cliente.cidade || $json.cidade || '',
  produto_interesse: cliente.produto_interesse || $json.produto_interesse || ''
};

const produtoIndicado =
  $json.produto_indicado ||
  $json.produtoIndicado ||
  cliente.produto_interesse ||
  '';

const segmentoIndicado =
  $json.segmento_indicado ||
  $json.segmentoIndicado ||
  $json.segmentoDetalhe ||
  $json.segmento ||
  '';

const quantidadeCalculada =
  $json.quantidade_calculada ||
  $json.quantidadeCalculada ||
  '';

const kitRecomendado =
  $json.kit_recomendado ||
  $json.kitRecomendado ||
  '';

let linkProduto =
  $json.linkProduto ||
  $json.link_produto ||
  '';

// Se já tiver produto indicado e existir link oficial na base, usa ele
if (!linkProduto && produtoIndicado && linksProdutos[produtoIndicado]) {
  linkProduto = linksProdutos[produtoIndicado];
}

// Segurança: só aceita link oficial da Sua Empresa
if (linkProduto && !String(linkProduto).toLowerCase().includes('suaempresa.com.br')) {
  linkProduto = '';
}

const historicoFormatado = historico
  .slice(-8)
  .map((m) => {
    const role = m.role || m.tipo || 'cliente';
    const content = m.content || m.mensagem || '';
    return `${role}: ${content}`;
  })
  .join('\n');

// EXEMPLO: adapte estes textos para o seu negócio.
const guiaProdutosEssencial = `
GUIA INTERNO DE INDICAÇÃO:
PROD-A — uso geral, ideal para iniciantes.
PROD-B — uso geral com acabamento superior.
PROD-PRO — aplicações profissionais que exigem alta resistência.
`.trim();

const regrasCalculo = `
Só calcule quantidade quando o cliente informar as medidas do projeto.
Se faltar alguma medida, pergunte apenas a medida que falta.
`.trim();

const regraKits = `
Recomende somente tamanhos que existem na base de produtos.
Se a quantidade calculada ficar entre dois tamanhos, indique o maior.
`.trim();

const politicaFrete = `
Nunca prometa frete grátis para um pedido específico.
Para prazo e valor de frete, oriente o cliente a simular no carrinho do site.
`.trim();

const regraLinks = `
Use somente links da base oficial. Nunca invente URLs.
Se não houver link do produto, envie apenas o site oficial.
`.trim();

const systemPrompt = `
Você é a Bia, atendente virtual da Sua Empresa no WhatsApp.

OBJETIVO:
Atender de forma humana, clara e comercial.
Ajudar o cliente a escolher o produto correto.
Calcular quantidade quando houver dados suficientes.
Conduzir naturalmente para a compra quando fizer sentido.

FUNÇÃO DESTE NODE:
Este node responde apenas as conversas consultivas.
Catálogo geral, detalhe de linha e lead de anúncio são tratados por outros nodes do fluxo.

TOM DE VOZ:
Profissional, acolhedor, claro e natural para WhatsApp.
Comercial sem pressionar.
No máximo 1 emoji quando fizer sentido.
Sem gírias e sem Markdown.

CONTINUIDADE:
Leia o histórico antes de responder.
Não cumprimente de novo se a conversa já começou.
Faça no máximo uma pergunta por mensagem.
`.trim();

const dadosContexto = {
  cliente: dadosLead,
  conversaEmAndamento,
  intencao: $json.intencao || '',
  mensagemAtual,
  produtoIndicado,
  segmentoIndicado,
  quantidadeCalculada,
  kitRecomendado,
  siteOficial,
  linkProduto,
  linksProdutos
};

const mensagemParaIA = `
DADOS DO ATENDIMENTO:
${JSON.stringify(dadosContexto, null, 2)}

HISTÓRICO RECENTE:
${historicoFormatado || 'Sem histórico recente.'}

GUIA ESSENCIAL DE PRODUTOS:
${guiaProdutosEssencial}

REGRAS DE CÁLCULO:
${regrasCalculo}

REGRAS DE KIT:
${regraKits}

POLÍTICA DE FRETE:
${politicaFrete}

REGRAS DE LINKS:
${regraLinks}

MENSAGEM ATUAL DO CLIENTE:
${mensagemAtual}

INSTRUÇÃO FINAL:
Responda como Bia, atendente da Sua Empresa no WhatsApp.
Não apresente catálogo geral.
Não misture todos os segmentos.
Responda somente o que faz sentido para a mensagem atual.
Não use Markdown nem asteriscos.
Não cumprimente de novo se a conversa já começou.
Não chame o cliente pelo nome se a conversa já estiver em andamento.
Faça no máximo uma pergunta principal.
Se já houver produto indicado, conduza naturalmente para o próximo passo.
Nunca afirme que o pedido do cliente deu frete grátis.
Nunca diga que o kit indicado atinge frete grátis.
Se o cliente perguntar sobre frete, informe somente a política geral de frete grátis e oriente a simular no carrinho.
Nunca invente links.
Nunca crie URL de produto.
Nunca use suaempresa.store.
Nunca use domínio diferente de suaempresa.com.br.
Se linkProduto estiver preenchido, pode enviar esse link.
Se linkProduto estiver vazio, envie apenas www.suaempresa.com.br quando o cliente pedir link, preço, valor ou compra.
`.trim();

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': apiKey,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: {
    model: 'claude-sonnet-4-5-20250929',
    max_tokens: 350,
    temperature: 0.25,
    system: systemPrompt,
    messages: [
      {
        role: 'user',
        content: mensagemParaIA
      }
    ]
  },
  json: true
});

let textoResposta = response?.content?.[0]?.text || '';

textoResposta = textoResposta
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
  .replace(/^["“”]+|["“”]+$/g, '')
  .trim();

if (!textoResposta) {
  throw new Error('Resposta vazia da IA: ' + JSON.stringify(response));
}

textoResposta = textoResposta
  .replace(/^opa[!,.\s]*/i, 'Olá! ')
  .replace(/\bmassa\b/gi, 'Perfeito')
  .replace(/\btri\b/gi, 'Ótimo')
  .replace(/\bbah\b/gi, '')
  .replace(/\btchê\b/gi, '')
  .replace(/\bshow de bola\b/gi, 'Perfeito')
  .replace(/\btop\b/gi, 'ótimo')
  .replace(/\birado\b/gi, 'muito bom')
  .replace(/\blegal demais\b/gi, 'muito legal')
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/\*(.*?)\*/g, '$1')
  .replace(/__(.*?)__/g, '$1')
  .replace(/_(.*?)_/g, '$1')
  .replace(/`([^`]+)`/g, '$1')
  .replace(/\*/g, '')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/^\s*[-•*]\s+/gm, '')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/[ \t]+([,.!?])/g, '$1')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// Segurança extra: troca/remova qualquer domínio/link inventado antes de sair do node
textoResposta = textoResposta
  .replace(/https?:\/\/(?:www\.)?suaempresa\.store[^\s]*/gi, siteOficial)
  .replace(/(?:www\.)?suaempresa\.store[^\s]*/gi, siteOficial)
  .replace(/https?:\/\/(?:www\.)?suaempresa\.com[^\s]*/gi, siteOficial)
  .replace(/(?:www\.)?suaempresa\.com[^\s]*/gi, siteOficial)
  .replace(/https?:\/\/loja\.suaempresa[^\s]*/gi, siteOficial)
  .replace(/loja\.suaempresa[^\s]*/gi, siteOficial);

const urlsResposta = textoResposta.match(/https?:\/\/[^\s]+|www\.[^\s]+/gi) || [];

for (const url of urlsResposta) {
  const ehOficial = url.toLowerCase().includes('suaempresa.com.br');

  if (!ehOficial) {
    textoResposta = textoResposta.replace(url, siteOficial);
  }
}

if (conversaEmAndamento) {
  textoResposta = textoResposta
    .replace(/^(oi|olá|ola|bom dia|boa tarde|boa noite)[,!\s]+[^.!?\n]{0,40}[.!?\n]?\s*/i, '')
    .replace(/^tudo bem\??\s*/i, '')
    .replace(/^bem[- ]vindo[a]? à sua empresa[.!?\s]*/i, '')
    .replace(/^bem[- ]vindo[a]? à suaempresa[.!?\s]*/i, '')
    .replace(/^como posso te ajudar hoje[?!.]?\s*/i, '')
    .trim();
}

if (!textoResposta) {
  textoResposta = 'Perfeito. Me conta só mais um detalhe para eu te orientar certinho.';
}

if (textoResposta.length > 650) {
  textoResposta = textoResposta.slice(0, 650).trim();

  const ultimoPonto = Math.max(
    textoResposta.lastIndexOf('.'),
    textoResposta.lastIndexOf('?'),
    textoResposta.lastIndexOf('!')
  );

  if (ultimoPonto > 250) {
    textoResposta = textoResposta.slice(0, ultimoPonto + 1).trim();
  }
}

return [
  {
    json: {
      ...$json,
      numero: telefone,
      telefone,
      remoteJid,
      mensagem: mensagemAtual,
      pushName: nomeCliente,
      textoResposta,
      conversaEmAndamento,
      historico_recente: historico,
      siteOficial,
      linkProduto,
      linksProdutos,
      origemResposta: 'chamar_ia'
    }
  }
];

if (!$json.textoResposta) {
  return [];
}

const numeroRaw =
  $json.numero ||
  $json.telefone ||
  $json.cliente?.telefone ||
  $json.remoteJid ||
  $json.remote_jid_atual ||
  '';

let numero = String(numeroRaw)
  .replace('@s.whatsapp.net', '')
  .replace('@lid', '')
  .replace(/\D/g, '');

let textoResposta = String($json.textoResposta || '')
  // Remove caracteres invisíveis
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')

  // Remove Markdown/negrito/itálico
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/\*(.*?)\*/g, '$1')
  .replace(/__(.*?)__/g, '$1')
  .replace(/_(.*?)_/g, '$1')
  .replace(/`([^`]+)`/g, '$1')

  // Remove qualquer asterisco restante
  .replace(/\*/g, '')

  // Remove espaços duplicados, mas mantém quebras de linha
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/[ \t]+([,.!?])/g, '$1')

  // Mantém parágrafos
  .replace(/\n{3,}/g, '\n\n')

  .trim();

if (!numero) {
  throw new Error(
    'Número não encontrado para envio. Campos recebidos: ' +
    JSON.stringify(Object.keys($json))
  );
}

if (!textoResposta) {
  throw new Error('Texto da resposta vazio');
}

const bodyEnvio = {
  number: numero,
  text: textoResposta
};

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `http://evolution:8080/message/sendText/${$env.EVOLUTION_INSTANCE_NAME}`,
    headers: {
      apikey: $env.EVOLUTION_API_KEY,
      'Content-Type': 'application/json'
    },
    body: bodyEnvio,
    json: true
  });

  return [
    {
      json: {
        ...$json,
        numero,
        remoteJid: $json.remoteJid || $json.remote_jid_atual || '',
        mensagem: $json.mensagem || $json.mensagem_atual || '',
        pushName: $json.pushName || $json.cliente?.nome || '',
        textoResposta,
        enviado: true,
        bodyEnviado: bodyEnvio,
        response
      }
    }
  ];
} catch (error) {
  return [
    {
      json: {
        ...$json,
        enviado: false,
        numero,
        textoResposta,
        bodyEnviado: bodyEnvio,
        erroMensagem: error.message,
        erroStatus: error.statusCode || error.response?.statusCode,
        erroBody: error.response?.body || error.error || error.cause || error
      }
    }
  ];
}

if (!$json.textoResposta) {
  return [];
}

const textoOriginal = String($json.textoResposta || '');

let textoResposta = textoOriginal
  // Remove caracteres invisíveis
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')

  // Remove Markdown/negrito/itálico
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/\*(.*?)\*/g, '$1')
  .replace(/__(.*?)__/g, '$1')
  .replace(/_(.*?)_/g, '$1')
  .replace(/`([^`]+)`/g, '$1')

  // Remove qualquer asterisco restante
  .replace(/\*/g, '')

  // Remove títulos Markdown
  .replace(/^#{1,6}\s+/gm, '')

  // Remove bullets simples no início de linhas
  .replace(/^\s*[-•]\s+/gm, '')

  // Ajusta expressões fora do tom desejado
  .replace(/\bopa\b/gi, 'Olá')
  .replace(/\bmassa\b/gi, 'Perfeito')
  .replace(/\btri\b/gi, 'Ótimo')
  .replace(/\bbah\b/gi, '')
  .replace(/\btchê\b/gi, '')
  .replace(/\bshow de bola\b/gi, 'Perfeito')
  .replace(/\btop\b/gi, 'ótimo')
  .replace(/\birado\b/gi, 'muito bom')
  .replace(/\blegal demais\b/gi, 'muito legal')

  // Remove espaços duplicados, mas mantém quebras de linha
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/[ \t]+([,.!?])/g, '$1')

  // Mantém parágrafos, mas remove excesso de linhas vazias
  .replace(/\n{3,}/g, '\n\n')

  .trim();

if (!textoResposta) {
  textoResposta = 'Perfeito. Me conta só mais um detalhe para eu te orientar certinho.';
}

// Remove nome do cliente no início de respostas repetidas
const nomeCliente = String($json.pushName || $json.cliente?.nome || '')
  .trim()
  .split(' ')[0];

if (nomeCliente) {
  const nomeRegex = new RegExp(`^(olá|oi|perfeito|ótimo|certo|entendi|que legal|excelente|boa)[,\\s]+${nomeCliente}[!,\\.\\s]*`, 'i');

  textoResposta = textoResposta
    .replace(nomeRegex, '$1. ')
    .replace(new RegExp(`^${nomeCliente}[!,\\.\\s]+`, 'i'), '')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

const limiteCaracteres =
  $json.tipoResposta === 'catalogo_produtos' ? 1200 :
  $json.tipoResposta === 'detalhe_segmento' ? 1200 :
  650;

if (textoResposta.length > limiteCaracteres) {
  textoResposta = textoResposta.slice(0, limiteCaracteres).trim();

  const ultimoPonto = Math.max(
    textoResposta.lastIndexOf('.'),
    textoResposta.lastIndexOf('?'),
    textoResposta.lastIndexOf('!')
  );

  if (ultimoPonto > 250) {
    textoResposta = textoResposta.slice(0, ultimoPonto + 1).trim();
  }
}
const frasesFreteProibidas = [
  /seu pedido.*frete grátis/gi,
  /sua compra.*frete grátis/gi,
  /esse kit.*frete grátis/gi,
  /esse produto.*frete grátis/gi,
  /atinge.*frete grátis/gi,
  /fecha.*frete grátis/gi,
  /dá frete grátis/gi,
  /fica com frete grátis/gi,
  /vai ter frete grátis/gi,
  /tem frete grátis para você/gi
];

const mencionouFreteGratisIndevido = frasesFreteProibidas.some((regex) =>
  regex.test(textoResposta)
);

if (mencionouFreteGratisIndevido) {
  textoResposta = `Temos política de frete grátis conforme a região:

Sul: a partir de R$ 199,00
Sudeste: a partir de R$ 299,00
Demais regiões: a partir de R$ 849,00

Para confirmar se o seu pedido terá frete grátis, prazo ou valor de entrega, é só simular no carrinho do site.`;
}

return [
  {
    json: {
      ...$json,
      numero: $json.numero || $json.telefone || $json.cliente?.telefone || '',
      textoResposta,
      textoOriginal
    }
  }
];

const mensagemAtual = String($json.mensagem_atual || $json.mensagem || '');

const texto = mensagemAtual
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

let intencao = 'atendimento_geral';
let segmentoDetalhe = null;

const mensagemFacebookLead =
  texto.includes('ola tenho interesse e queria saber mais informacoes por favor') ||
  texto.includes('olá tenho interesse e queria saber mais informações por favor') ||
  texto.includes('tenho interesse e queria saber mais informacoes') ||
  texto.includes('tenho interesse e queria saber mais informações');

// Detecta saudações simples, mesmo com combinações tipo:
// "oi bom dia", "oii boa tarde", "olá tudo bem", "bom dia"
const textoSemPontuacao = texto
  .replace(/[!?.,;:]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const saudacoesPermitidas = [
  'oi',
  'oii',
  'oiii',
  'ola',
  'olá',
  'bom dia',
  'boa tarde',
  'boa noite',
  'tudo bem',
