  texto.includes('conhecer produtos') ||
  texto.includes('produtos da suaempresa') ||
  texto.includes('produtos suaempresa') ||
  texto.includes('produtos da empresa') ||
  texto.includes('quais produtos') ||
  texto.includes('quais linhas') ||
  texto.includes('catalogo') ||
  texto.includes('catálogo') ||
