  texto.includes('o que voces vendem') ||
  texto.includes('o que vocês vendem') ||
  texto.includes('me apresenta os produtos') ||
  texto.includes('me mostre os produtos') ||
  texto.includes('quero ver os produtos') ||
  texto.includes('trabalham com quais linhas');

if (saudacaoSimples) {
  intencao = 'saudacao';
}

if (pediuCatalogo) {
  intencao = 'catalogo_produtos';
}

if (mensagemFacebookLead) {
  intencao = 'lead_facebook_inicial';
}

return [
