return [{ json: { ...$json, baseProdutos } }];

// Detalha uma linha de produtos a partir da base, sem chamar a IA.
const segmentoKey = $json.segmentoDetalhe;
const segmento = $json.baseProdutos?.segmentos?.[segmentoKey];

if (!segmentoKey || !segmento) {
  return [];
}

const produtos = (segmento.produtos || [])
  .map((p) => `${p.codigo}\n${p.indicacao}`)
  .join('\n\n');

const textoResposta = `${segmento.nome}: ${segmento.descricao}\n\n${produtos}\n\nMe conta qual peça você quer fazer que eu te indico a melhor opção.`;

return [{ json: { ...$json, textoResposta, tipoResposta: 'detalhe_segmento', origemResposta: 'resposta_detalhe_segmento' } }];

if (!$json.textoResposta) {
  return [];
}

let textoResposta = String($json.textoResposta || '').trim();

const textoOriginalValidacao = textoResposta;

// 1. Remove caracteres invisíveis
textoResposta = textoResposta
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
  .trim();

// 2. Remove Markdown, asteriscos, negrito, itálico e crases
textoResposta = textoResposta
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/\*(.*?)\*/g, '$1')
  .replace(/__(.*?)__/g, '$1')
  .replace(/_(.*?)_/g, '$1')
  .replace(/`([^`]+)`/g, '$1')
  .replace(/\*/g, '')
  .replace(/^#{1,6}\s+/gm, '')
  .trim();

// 3. Corrige gírias/expressões fora do tom
const substituicoesTom = [
  { regex: /^opa[!,.\s]*/i, replace: 'Olá! ' },
  { regex: /\bmassa\b/gi, replace: 'Perfeito' },
  { regex: /\btri\b/gi, replace: 'Ótimo' },
  { regex: /\bbah\b/gi, replace: '' },
  { regex: /\btchê\b/gi, replace: '' },
  { regex: /\bshow de bola\b/gi, replace: 'Perfeito' },
  { regex: /\btop\b/gi, replace: 'ótimo' },
  { regex: /\birado\b/gi, replace: 'muito bom' },
  { regex: /\blegal demais\b/gi, replace: 'muito legal' }
];

for (const item of substituicoesTom) {
  textoResposta = textoResposta.replace(item.regex, item.replace);
}

// 4. Bloqueio de links/domínios errados
const siteOficial = 'www.suaempresa.com.br';

textoResposta = textoResposta
  .replace(/https?:\/\/(?:www\.)?suaempresa\.store[^\s]*/gi, siteOficial)
  .replace(/(?:www\.)?suaempresa\.store[^\s]*/gi, siteOficial)
  .replace(/https?:\/\/(?:www\.)?suaempresa\.com[^\s]*/gi, siteOficial)
  .replace(/(?:www\.)?suaempresa\.com[^\s]*/gi, siteOficial)
  .replace(/https?:\/\/loja\.suaempresa[^\s]*/gi, siteOficial)
  .replace(/loja\.suaempresa[^\s]*/gi, siteOficial);

// Remove/substitui qualquer URL fora do domínio oficial
const urls = textoResposta.match(/https?:\/\/[^\s]+|www\.[^\s]+/gi) || [];

for (const url of urls) {
  const urlNormalizada = url.toLowerCase();

  const ehOficial = urlNormalizada.includes('suaempresa.com.br');

  if (!ehOficial) {
    textoResposta = textoResposta.replace(url, siteOficial);
  }
}

// Corrige domínio solto sem http/www
textoResposta = textoResposta
  .replace(/suaempresa\.store/gi, siteOficial)
  .replace(/suaempresa\.com/gi, siteOficial);

// 5. Trava contra frete grátis indevido
const frasesFreteProibidas = [
  /seu pedido.*frete grátis/gi,
  /sua compra.*frete grátis/gi,
  /esse kit.*frete grátis/gi,
  /esse produto.*frete grátis/gi,
  /atinge.*frete grátis/gi,
  /fecha.*frete grátis/gi,
  /dá frete grátis/gi,
  /da frete gratis/gi,
  /fica com frete grátis/gi,
  /fica com frete gratis/gi,
  /vai ter frete grátis/gi,
  /vai ter frete gratis/gi,
  /tem frete grátis para você/gi,
  /tem frete gratis para você/gi,
  /tem frete gratis pra você/gi,
  /tem frete grátis pra você/gi
];

const mencionouFreteGratisIndevido = frasesFreteProibidas.some((regex) =>
  regex.test(textoResposta)
);

if (mencionouFreteGratisIndevido) {
  textoResposta = `Temos política de frete grátis conforme a região:

Sul: a partir de R$ 199,00
Sudeste: a partir de R$ 299,00
Demais regiões: a partir de R$ 849,00

Para confirmar se o seu pedido terá frete grátis, prazo ou valor de entrega, é só simular no carrinho do site:
www.suaempresa.com.br`;
}

// 6. Trava contra valor de frete inventado
const falouValorFrete =
  /frete/i.test(textoResposta) &&
  /R\$\s?\d+/i.test(textoResposta) &&
  !/R\$\s?199/i.test(textoResposta) &&
  !/R\$\s?299/i.test(textoResposta) &&
  !/R\$\s?849/i.test(textoResposta);

if (falouValorFrete) {
  textoResposta = `Para frete, seguimos a política de frete grátis:

Sul: a partir de R$ 199,00
Sudeste: a partir de R$ 299,00
Demais regiões: a partir de R$ 849,00

Para confirmar prazo ou valor de entrega, é só simular no carrinho do site:
www.suaempresa.com.br`;
}

// 7. Trava contra prazo inventado
const falouPrazoEntrega =
  /(chega|entrega|recebe|prazo).*?(\d+\s?(dias|dia|úteis|uteis))/i.test(textoResposta) ||
  /(\d+\s?(dias|dia|úteis|uteis)).*?(chega|entrega|recebe)/i.test(textoResposta);

if (falouPrazoEntrega) {
  textoResposta = textoResposta
    .replace(/[^.!?]*?(chega|entrega|recebe|prazo)[^.!?]*?(\d+\s?(dias|dia|úteis|uteis))[^.!?]*[.!?]?/gi, '')
    .replace(/[^.!?]*?(\d+\s?(dias|dia|úteis|uteis))[^.!?]*?(chega|entrega|recebe)[^.!?]*[.!?]?/gi, '')
    .trim();

  textoResposta += `\n\nPara prazo de entrega, é necessário simular no carrinho do site:\nwww.suaempresa.com.br`;
}

// 8. Trava contra preço inventado
// Permite somente valores da política de frete grátis.
// Se aparecer outro valor em R$, substitui por orientação segura.
const valoresEncontrados = textoResposta.match(/R\$\s?\d+(?:[.,]\d{2})?/g) || [];

const valoresPermitidos = [
  'R$ 199,00',
  'R$199,00',
  'R$ 299,00',
  'R$299,00',
  'R$ 849,00',
  'R$849,00'
];

const temValorNaoPermitido = valoresEncontrados.some((valor) => {
  const normalizado = valor.replace(/\s+/g, ' ').trim();
  return !valoresPermitidos.includes(normalizado);
});

if (temValorNaoPermitido && !/frete grátis|frete gratis/i.test(textoResposta)) {
  textoResposta = `Para valores atualizados, o ideal é conferir diretamente no site oficial da Sua Empresa:

www.suaempresa.com.br

Posso te ajudar indicando o produto correto para o seu projeto.`;
}

// 9. Trava contra promessa de estoque/disponibilidade
const frasesEstoqueProibidas = [
  /temos em estoque/gi,
  /tem estoque/gi,
  /está disponível/gi,
  /esta disponivel/gi,
  /pronta entrega/gi,
  /envio imediato/gi
];

const mencionouEstoque = frasesEstoqueProibidas.some((regex) =>
  regex.test(textoResposta)
);

if (mencionouEstoque) {
  textoResposta = textoResposta
    .replace(/temos em estoque/gi, 'você pode conferir a disponibilidade')
    .replace(/tem estoque/gi, 'é possível conferir a disponibilidade')
    .replace(/está disponível/gi, 'pode ter disponibilidade confirmada')
    .replace(/esta disponivel/gi, 'pode ter disponibilidade confirmada')
    .replace(/pronta entrega/gi, 'com disponibilidade a confirmar')
    .replace(/envio imediato/gi, 'com envio a confirmar')
    .trim();
}

// 10. Padroniza nomes de produtos escritos com espaços errados
const produtosPadronizados = [
  ['PROD A', 'PROD-A'],
  ['PROD B', 'PROD-B'],
  ['PROD PRO', 'PROD-PRO']
];

for (const [errado, correto] of produtosPadronizados) {
  const regex = new RegExp(`\\b${errado}\\b`, 'gi');
  textoResposta = textoResposta.replace(regex, correto);
}

// 11. Remove excesso de espaços sem apagar quebras de linha
textoResposta = textoResposta
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/[ \t]+([,.!?])/g, '$1')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// 12. Limite final por tipo de resposta
const limiteCaracteres =
  $json.tipoResposta === 'catalogo_produtos' ? 1200 :
  $json.tipoResposta === 'detalhe_segmento' ? 1200 :
  $json.tipoResposta === 'lead_facebook_inicial' ? 1200 :
  750;

if (textoResposta.length > limiteCaracteres) {
  textoResposta = textoResposta.slice(0, limiteCaracteres).trim();

  const ultimoPonto = Math.max(
    textoResposta.lastIndexOf('.'),
    textoResposta.lastIndexOf('?'),
    textoResposta.lastIndexOf('!')
  );

  if (ultimoPonto > 250) {
    textoResposta = textoResposta.slice(0, ultimoPonto + 1).trim();
  }
}

// 13. Segurança final
if (!textoResposta) {
  textoResposta = 'Perfeito. Me conta só mais um detalhe para eu te orientar certinho.';
}

return [
  {
    json: {
      ...$json,
      textoResposta,
      textoOriginalValidacao,
      validado: true,
      dominioValidado: true,
      siteOficial,
      origemValidacao: 'validador_final'
    }
  }
];

// Primeira resposta para quem chega por anúncio (mensagem automática do Facebook/Instagram).
const textoResposta = `Olá! Seja muito bem-vindo à Sua Empresa 😊
Aqui é a Bia, e será um prazer te atender.

Para te orientar da melhor forma, me conta: qual projeto você tem em mente?

Você também pode conhecer todos os nossos produtos em:
www.suaempresa.com.br`;

return [{ json: { ...$json, textoResposta, tipoResposta: 'lead_facebook_inicial', origemResposta: 'resposta_lead_facebook' } }];

const siteOficial = 'www.suaempresa.com.br';

const produtosComerciais = {
  'PROD-A': {
    nome: 'PROD-A',
    tamanhos: ['500g', '1kg'],
    linksPorTamanho: {
      '500g': 'https://www.suaempresa.com.br/produtos/prod-a-500g',
      '1kg': 'https://www.suaempresa.com.br/produtos/prod-a-1kg'
    },
    linkCategoria: 'https://www.suaempresa.com.br/linha-basica'
  },
  'PROD-PRO': {
    nome: 'PROD-PRO',
    tamanhos: ['5kg'],
    linksPorTamanho: {
      '5kg': 'https://www.suaempresa.com.br/produtos/prod-pro-5kg'
    },
    linkCategoria: 'https://www.suaempresa.com.br/linha-profissional'
  }
};

const aliasesProdutos = {
  'prod-a': 'PROD-A',
  'prod a': 'PROD-A',
  'prod-b': 'PROD-B',
  'prod b': 'PROD-B',
  'prod-pro': 'PROD-PRO',
  'prod pro': 'PROD-PRO'
};

const mensagem = String(
  $json.mensagem_atual ||
  $json.mensagem ||
  $json.ultima_mensagem ||
  ''
)
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

let produtoDetectado = '';

for (const [alias, produto] of Object.entries(aliasesProdutos)) {
  const aliasNormalizado = alias
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  if (mensagem.includes(aliasNormalizado)) {
    produtoDetectado = produto;
    break;
  }
}

const produtoComercial = produtoDetectado
  ? produtosComerciais[produtoDetectado]
  : null;

// Detecta tamanho citado pelo cliente, aceitando variações tipo:
// "1kg", "1 kg", "1,00kg", "1.00kg"
let tamanhoDetectado = '';

if (produtoComercial) {
  const mensagemNormalizada = mensagem
    .replace(',', '.')
    .replace(/\s+/g, '');

  for (const tamanho of produtoComercial.tamanhos) {
    const tamanhoNormalizado = tamanho
      .toLowerCase()
      .replace(',', '.')
      .replace(/\s+/g, '');

    const tamanhoSemZeros = tamanhoNormalizado
      .replace('1.00kg', '1kg')
      .replace('3.00kg', '3kg')
      .replace('6.00kg', '6kg')
      .replace('7.00kg', '7kg');

    const variacoes = [
      tamanhoNormalizado,
      tamanhoSemZeros,
      tamanhoNormalizado.replace('.', ',')
    ];

    if (variacoes.some(v => mensagemNormalizada.includes(v))) {
      tamanhoDetectado = tamanho;
      break;
    }
  }
}

// Define o link correto
let linkProduto = '';

// Se for categoria com link geral, usa o link da categoria
if (produtoComercial?.linkCategoria) {
  linkProduto = produtoComercial.linkCategoria;
}

// Se o cliente citar produto + tamanho, pega o link específico daquele tamanho
if (
  produtoComercial &&
  tamanhoDetectado &&
  produtoComercial.linksPorTamanho?.[tamanhoDetectado]
) {
  linkProduto = produtoComercial.linksPorTamanho[tamanhoDetectado];
}

// Segurança: só aceita link oficial da Sua Empresa
if (linkProduto && !linkProduto.toLowerCase().includes('suaempresa.com.br')) {
  linkProduto = '';
}

// Links oficiais do produto detectado
const linksDoProdutoDetectado = produtoComercial
  ? {
      linksPorTamanho: produtoComercial.linksPorTamanho || {},
      linkCategoria: produtoComercial.linkCategoria || ''
    }
  : {};

// Todos os links por produto/categoria
const linksProdutos = Object.fromEntries(
  Object.entries(produtosComerciais).map(([codigo, dados]) => [
    codigo,
    {
      linksPorTamanho: dados.linksPorTamanho || {},
      linkCategoria: dados.linkCategoria || ''
    }
  ])
);

return [
  {
    json: {
      ...$json,
      siteOficial,
      produtosComerciais,
      linksProdutos,
      produtoDetectado,
      produtoComercial,
      tamanhoDetectado,
      linksDoProdutoDetectado,
      linkProduto,
      produtoIndicado: $json.produtoIndicado || produtoDetectado || '',
      produto_indicado: $json.produto_indicado || produtoDetectado || ''
    }
  }
];
